package org.transittr;
import java.io.*;import java.net.URLEncoder;import java.util.*;import org.json.*;
/** Public stop arrivals and route data used by the supplied Kentkart mobile applications. */
public final class KentClient {
 public static String region(int city){return city==3?"004":"026";}
 public static String url(int city,String path){return "https://service.kentkart.com/rl1/"+path+(path.indexOf('?')>=0?"&":"?")+"region="+region(city)+"&authType=4";}
 static JSONObject get(int city,String path)throws IOException{try{String body;if(city==8&&(path.startsWith("api/bus/closest?")||path.startsWith("api/v2.0/route/info?"))){String endpoint=path.startsWith("api/bus/")?"/web/nearest/bus":"/web/pathInfo";String query=path.substring(path.indexOf('?')+1);String target="https://service.kentkart.com/rl1/"+endpoint+"?region=026&lang=tr&authType=4&"+query+"&version="+URLEncoder.encode(KentWebSignature.version(),"UTF-8");if(endpoint.equals("/web/nearest/bus"))target+="&accuracy=0&lat=36.897087&lng=30.713777";body=ApiHttp.text(target,null,null,KentWebSignature.headers(endpoint),4194304);}else body=ApiHttp.get(url(city,path));JSONObject d=new JSONObject(body);if(d.has("result")&&d.getJSONObject("result").optInt("code",-1)!=0)throw new IOException("Kentkart veri servisi yanıt vermedi");return d;}catch(JSONException e){throw new IOException("Kentkart veri biçimi değişti");}}
 public static JourneyData.Snapshot query(int city,String stop,String filter)throws IOException{try{return parse(get(city,"api/bus/closest?busStopId="+URLEncoder.encode(stop,"UTF-8")),city,stop,filter);}catch(JSONException e){throw new IOException("Kentkart varışları okunamadı");}}
 public static JourneyData.Snapshot parse(JSONObject d,int city,String stop,String filter)throws JSONException,IOException{
  JourneyData.Snapshot s=new JourneyData.Snapshot();s.source=city==3?"Kocaeli e-komobil / Kentkart":"Antalyakart / Kentkart";JSONArray buses=d.optJSONArray("busList");if(buses==null)throw new IOException("Kentkart araç listesi bulunamadı");if(buses.length()>200)throw new IOException("Araç sınırı");
  for(int i=0;i<buses.length();i++){JSONObject r=buses.getJSONObject(i);String line=SourceTools.text(r,"displayRouteCode");if(!SourceTools.matches(line,filter))continue;JourneyData.Vehicle v=new JourneyData.Vehicle();v.id="kent:"+region(city)+":"+r.optString("busId");v.line=line;v.name=r.optString("headSign",r.optString("displayName",""));v.lat=SourceTools.number(r,"lat");v.lon=SourceTools.number(r,"lng");v.routeCode=r.optString("shapeId");String minutes=SourceTools.text(r,"timeDiff");try{double m=Double.parseDouble(minutes);v.etaSeconds=m>=0&&m<1440?(long)Math.ceil(m*60):-1;}catch(Exception ignored){}v.eta=SourceTools.minutes(v.etaSeconds);v.arrivalStop=stop;v.etaIsStopArrival=v.etaSeconds>=0;s.rows.add(v);}
  SourceTools.sort(s);if(s.rows.isEmpty())s.message="Bu durak ve hat için yaklaşan araç yok.";return s;
 }
 public static JourneyData.Station stop(int city,String code)throws IOException{try{JSONArray rows=get(city,"api/trip/search?keyword="+URLEncoder.encode(code,"UTF-8")).getJSONArray("stopList");for(int k=0;k<rows.length();k++){JSONObject r=rows.getJSONObject(k);if(code.equals(r.optString("stopId"))){JourneyData.Station s=new JourneyData.Station(r.optString("name",code),SourceTools.number(r,"lat"),SourceTools.number(r,"lng"));s.code=code;return s;}}return null;}catch(JSONException e){throw new IOException("Durak konumu okunamadı");}}
 public static JourneyData.Route route(int city,String code,String name)throws IOException{try{JSONObject d=get(city,"api/v2.0/route/info?displayRouteCode="+URLEncoder.encode(code,"UTF-8")+"&direction=0&resultType=111111&shapeId=&busStopId=");JSONArray paths=d.optJSONArray("pathList");JourneyData.Route out=new JourneyData.Route();out.code=code;out.name=name;out.source="Kentkart mobil güzergâh servisi";out.schematic=false;if(paths==null||paths.length()==0)throw new IOException("Hat güzergâhı bulunamadı");JSONObject p=paths.getJSONObject(0);JSONArray points=p.optJSONArray("pointList"),stops=p.optJSONArray("busStopList");ArrayList<JourneyData.Station> part=new ArrayList<JourneyData.Station>();if(points!=null)for(int i=0;i<points.length()&&i<20000;i++){JSONObject r=points.getJSONObject(i);JourneyData.Station s=new JourneyData.Station("",SourceTools.number(r,"lat"),SourceTools.number(r,"lng"));if(s.lat>=35&&s.lat<=43&&s.lon>=25&&s.lon<=45)part.add(s);}if(part.size()>1)out.parts.add(part);if(stops!=null)for(int i=0;i<stops.length()&&i<1000;i++){JSONObject r=stops.getJSONObject(i);JourneyData.Station s=new JourneyData.Station(r.optString("stopName",r.optString("busStopName","")),SourceTools.number(r,"lat"),SourceTools.number(r,"lng"));s.code=r.optString("stopId",r.optString("busStopId",""));out.stops.add(s);if(s.lat>=35&&s.lat<=43&&s.lon>=25&&s.lon<=45)out.mappedStops++;}return out;}catch(JSONException e){throw new IOException("Hat güzergâhı okunamadı");}}
}
